    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Resistencia equivalente total",
        "pregunta": "Calcule la resistencia equivalente total $R_{eq}$ del lazo serie.",
        "pistas": [
          "Pista 1: Al estar en serie, simplemente sume las tres resistencias.",
          "Pista 2: $R_{eq} = R_1 + R_2 + R_3$.",
          "Pista 3: $2 + 4 + 6 = 12\\,\\Omega$."
        ],
        "explicacion": "$R_{eq} = R_1 + R_2 + R_3 = 2\\,\\Omega + 4\\,\\Omega + 6\\,\\Omega = 12\\,\\Omega$.",
        "tipoRespuesta": "numerica",
        "unidad": "Ω",
        "solucion": 12,
        "valorEsperado": 12,
        "tolerancia": 0.05,
        "simbolo": "R_{eq}",
        "explicacionPaso": "$R_{eq} = R_1 + R_2 + R_3 = 2 + 4 + 6 = 12.0\\,\\Omega$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente de la fuente",
        "pregunta": "Determine la corriente total $I$ entregada por la fuente.",
        "pistas": [
          "Pista 1: Aplique la Ley de Ohm general: $I = V_S / R_{eq}$.",
          "Pista 2: Divida $24\\text{ V} / 12\\,\\Omega$."
        ],
        "explicacion": "$I = \\frac{V_S}{R_{eq}} = \\frac{24\\text{ V}}{12\\,\\Omega} = 2.0\\text{ A}$.",
        "tipoRespuesta": "numerica",
        "unidad": "A",
        "solucion": 2,
        "valorEsperado": 2,
        "tolerancia": 0.05,
        "simbolo": "I",
        "explicacionPaso": "$I = \\frac{24\\text{ V}}{12\\,\\Omega} = 2.0\\text{ A}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Caída de tensión en R2",
        "pregunta": "Calcule la tensión $V_{R2}$ presente sobre el resistor $R_2$.",
        "pistas": [
          "Pista 1: Aplique Ley de Ohm en $R_2$: $V_{R2} = I \\cdot R_2$.",
          "Pista 2: O use divisor: $V_{R2} = V_S \\cdot (R_2 / R_{eq}) = 24 \\cdot (4 / 12)$.",
          "Pista 3: $2\\text{ A} \\cdot 4\\,\\Omega = 8\\text{ V}$."
        ],
        "explicacion": "$V_{R2} = I \\cdot R_2 = 2.0\\text{ A} \\cdot 4\\,\\Omega = 8.0\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 8,
        "valorEsperado": 8,
        "tolerancia": 0.05,
        "simbolo": "V_{R2}",
        "explicacionPaso": "$V_{R2} = I \\cdot R_2 = 2.0\\text{ A} \\cdot 4\\,\\Omega = 8.0\\text{ V}$."
      }
    ]
