    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Aporte de VS1 (con VS2 pasivada)",
        "pregunta": "Calcule la tensión $V_c'$ producida únicamente por la fuente $V_{S1}$.",
        "pistas": [
          "Pista 1: Cortocircuite $V_{S2}$ a masa. $R_2$ y $R_3$ quedan en paralelo.",
          "Pista 2: $R_p = R_2 \\parallel R_3 = (10 \\cdot 20) / (10 + 20) = 200 / 30 = 6.667\\,\\Omega$.",
          "Pista 3: Aplique divisor de tensión: $V_c' = 30 \\cdot \\frac{R_p}{R_1 + R_p} = 30 \\cdot \\frac{6.667}{5 + 6.667} = 17.14\\text{ V}$."
        ],
        "explicacion": "Con $V_{S2} = 0$: $R_2 \\parallel R_3 = \\frac{10 \\cdot 20}{30} = \\frac{20}{3}\\,\\Omega \\approx 6.67\\,\\Omega$. Por divisor de tensión: $V_c' = 30\\text{ V} \\cdot \\frac{20/3}{5 + 20/3} = 30 \\cdot \\frac{20}{35} = \\frac{120}{7} \\approx 17.14\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 17.14,
        "tolerancia": 0.05,
        "simbolo": "V_c'",
        "valorEsperado": 17.14,
        "explicacionPaso": "Con $V_{S2} = 0$: $R_2 \\parallel R_3 = \\frac{10 \\cdot 20}{30} = \\frac{20}{3}\\,\\Omega \\approx 6.67\\,\\Omega$. Por divisor de tensión: $V_c' = 30\\text{ V} \\cdot \\frac{20/3}{5 + 20/3} = 30 \\cdot \\frac{20}{35} = \\frac{120}{7} \\approx 17.14\\text{ V}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Aporte de VS2 (con VS1 pasivada)",
        "pregunta": "Calcule la tensión $V_c''$ producida únicamente por la fuente $V_{S2}$.",
        "pistas": [
          "Pista 1: Cortocircuite $V_{S1}$ a masa. Ahora $R_1$ y $R_2$ quedan en paralelo.",
          "Pista 2: $R_q = R_1 \\parallel R_2 = (5 \\cdot 10) / 15 = 50 / 15 = 3.333\\,\\Omega$.",
          "Pista 3: $V_c'' = 15 \\cdot \\frac{R_q}{R_3 + R_q} = 15 \\cdot \\frac{3.333}{20 + 3.333} = 15 \\cdot \\frac{10/3}{70/3} = 15 \\cdot \\frac{1}{7} = 2.14\\text{ V}$."
        ],
        "explicacion": "Con $V_{S1} = 0$: $R_1 \\parallel R_2 = \\frac{5 \\cdot 10}{15} = \\frac{10}{3}\\,\\Omega \\approx 3.33\\,\\Omega$. Por divisor: $V_c'' = 15\\text{ V} \\cdot \\frac{10/3}{20 + 10/3} = 15 \\cdot \\frac{10}{70} = \\frac{15}{7} \\approx 2.14\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 2.14,
        "tolerancia": 0.05,
        "simbolo": "V_c''",
        "valorEsperado": 2.14,
        "explicacionPaso": "Con $V_{S1} = 0$: $R_1 \\parallel R_2 = \\frac{5 \\cdot 10}{15} = \\frac{10}{3}\\,\\Omega \\approx 3.33\\,\\Omega$. Por divisor: $V_c'' = 15\\text{ V} \\cdot \\frac{10/3}{20 + 10/3} = 15 \\cdot \\frac{10}{70} = \\frac{15}{7} \\approx 2.14\\text{ V}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Tensión total superpuesta",
        "pregunta": "Sume ambos aportes para obtener la tensión total en el nodo $V_c$.",
        "pistas": [
          "Pista 1: Como ambas fuentes polarizan el nodo con signo positivo hacia masa, los aportes se suman.",
          "Pista 2: $V_c = V_c' + V_c'' = \\frac{120}{7} + \\frac{15}{7} = \\frac{135}{7}\\text{ V}$.",
          "Pista 3: $135 / 7 \\approx 19.29\\text{ V}$."
        ],
        "explicacion": "Superponiendo las respuestas parciales: $V_c = V_c' + V_c'' = 17.14\\text{ V} + 2.14\\text{ V} = 19.29\\text{ V}$ (o exactamente $135/7\\text{ V}$).",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 19.29,
        "tolerancia": 0.05,
        "simbolo": "V_c",
        "valorEsperado": 19.29,
        "explicacionPaso": "Superponiendo las respuestas parciales: $V_c = V_c' + V_c'' = 17.14\\text{ V} + 2.14\\text{ V} = 19.29\\text{ V}$ (o exactamente $135/7\\text{ V}$)."
      }
    ]
