        "explicacion": "$I_L = \\frac{V_Z}{R_L} = \\frac{10\\text{ V}}{1000\\,\\Omega} = 0.010\\text{ A} = 10.0\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 10,
        "valorEsperado": 10,
        "tolerancia": 0.05,
        "simbolo": "I_L",
        "explicacionPaso": "$I_L = \\frac{10\\text{ V}}{1000\\,\\Omega} \\times 1000 = 10.0\\text{ mA}$."
