    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Tensión Thévenin de base VBB",
        "pregunta": "Calcule la tensión Thévenin de base $V_{BB}$ (en Volts).",
        "pistas": [
          "Pista 1: Se obtiene aplicando el divisor de tensión sobre $R_2$ a circuito abierto.",
          "Pista 2: $V_{BB} = V_{CC} \\cdot \\frac{R_2}{R_1 + R_2}$.",
          "Pista 3: $15\\text{ V} \\cdot \\frac{10}{33 + 10} = 15 \\cdot \\frac{10}{43} = 3.488\\text{ V}$."
        ],
        "explicacion": "$V_{BB} = V_{CC} \\cdot \\frac{R_2}{R_1 + R_2} = 15\\text{ V} \\cdot \\frac{10\\text{ k}\\Omega}{43\\text{ k}\\Omega} \\approx 3.49\\text{ V}$. Además $R_{BB} = \\frac{33 \\cdot 10}{43} = 7.67\\text{ k}\\Omega$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 3.49,
        "tolerancia": 0.05,
        "simbolo": "V_{BB}",
        "valorEsperado": 3.49,
        "explicacionPaso": "$V_{BB} = V_{CC} \\cdot \\frac{R_2}{R_1 + R_2} = 15\\text{ V} \\cdot \\frac{10\\text{ k}\\Omega}{43\\text{ k}\\Omega} \\approx 3.49\\text{ V}$. Además $R_{BB} = \\frac{33 \\cdot 10}{43} = 7.67\\text{ k}\\Omega$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente de colector de reposo ICQ",
        "pregunta": "Determine la corriente de reposo $I_{CQ}$ (en mA).",
        "pistas": [
          "Pista 1: Aplique la ecuación de la malla de entrada con $R_{BB} = 7.67\\text{ k}\\Omega$.",
          "Pista 2: $I_B = \\frac{V_{BB} - V_{BE}}{R_{BB} + (\\beta + 1) R_E}$. Luego $I_C = \\beta I_B$.",
          "Pista 3: Denominador: $7.67\\text{ k}\\Omega + 101(1.0\\text{ k}\\Omega) = 108.67\\text{ k}\\Omega$. $I_B = (3.488 - 0.7) / 108.67\\text{ k}\\Omega = 2.788 / 108.67\\text{ k}\\Omega = 25.65\\,\\mu\\text{A}$. $I_C = 100 \\cdot 25.65\\,\\mu\\text{A} = 2.57\\text{ mA}$."
        ],
        "explicacion": "$I_B = \\frac{V_{BB} - V_{BE}}{R_{BB} + (\\beta + 1) R_E} = \\frac{3.488 - 0.7}{7.67\\text{ k}\\Omega + 101\\text{ k}\\Omega} = \\frac{2.788\\text{ V}}{108.67\\text{ k}\\Omega} \\approx 25.65\\,\\mu\\text{A}$.\\nCorriente de colector: $I_{CQ} = \\beta I_B = 100 \\cdot 25.65\\,\\mu\\text{A} = 2.57\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 2.57,
        "tolerancia": 0.05,
        "simbolo": "I_{CQ}",
        "valorEsperado": 2.57,
        "explicacionPaso": "$I_B = \\frac{V_{BB} - V_{BE}}{R_{BB} + (\\beta + 1) R_E} = \\frac{3.488 - 0.7}{7.67\\text{ k}\\Omega + 101\\text{ k}\\Omega} = \\frac{2.788\\text{ V}}{108.67\\text{ k}\\Omega} \\approx 25.65\\,\\mu\\text{A}$.\\nCorriente de colector: $I_{CQ} = \\beta I_B = 100 \\cdot 25.65\\,\\mu\\text{A} = 2.57\\text{ mA}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Tensión colector-emisor VCEQ",
        "pregunta": "Calcule la tensión $V_{CEQ}$ entre colector y emisor en reposo.",
        "pistas": [
          "Pista 1: Aplique LTK a la malla colector-emisor.",
          "Pista 2: $V_{CEQ} = V_{CC} - I_{CQ} R_C - I_E R_E \\approx V_{CC} - I_{CQ}(R_C + R_E)$.",
          "Pista 3: $15 - 2.57\\text{ mA}(2.2\\text{ k}\\Omega + 1.0\\text{ k}\\Omega) = 15 - 2.57(3.2) = 15 - 8.22 = 6.78\\text{ V}$."
        ],
        "explicacion": "Malla colector-emisor: $V_{CEQ} = V_{CC} - I_C R_C - I_E R_E \\approx 15\\text{ V} - 2.57\\text{ mA} \\cdot 3.2\\text{ k}\\Omega = 15 - 8.22 = 6.78\\text{ V}$. Como $V_{CEQ} > 0.2\\text{ V}$, el BJT opera cómodamente en la Zona Activa Directa.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 6.78,
        "tolerancia": 0.05,
        "simbolo": "V_{CEQ}",
        "valorEsperado": 6.78,
        "explicacionPaso": "Malla colector-emisor: $V_{CEQ} = V_{CC} - I_C R_C - I_E R_E \\approx 15\\text{ V} - 2.57\\text{ mA} \\cdot 3.2\\text{ k}\\Omega = 15 - 8.22 = 6.78\\text{ V}$. Como $V_{CEQ} > 0.2\\text{ V}$, el BJT opera cómodamente en la Zona Activa Directa."
      }
    ]
