    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Tensión de colector-emisor en corte",
        "pregunta": "Calcule la tensión $V_{CE,corte}$ cuando el transistor está completamente en corte ($I_C = 0$).",
        "pistas": [
          "Pista 1: Al no haber corriente ($I_C = 0$), las caídas en $R_C$ y $R_E$ son nulas.",
          "Pista 2: Toda la tensión de alimentación cae entre colector y emisor: $V_{CE,corte} = V_{CC}$.",
          "Pista 3: $V_{CE,corte} = 18\\text{ V}$."
        ],
        "explicacion": "En el punto de corte, el transistor no conduce ($I_C = 0$), por lo que $V_{CE} = V_{CC} = 18.0\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 18,
        "valorEsperado": 18,
        "tolerancia": 0.05,
        "simbolo": "V_{CE,corte}",
        "explicacionPaso": "$V_{CE,corte} = V_{CC} = 18.0\\text{ V}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente de colector de saturación",
        "pregunta": "Determine la corriente de saturación teórica $I_{C,sat}$ en la recta de carga (en mA).",
        "pistas": [
          "Pista 1: En saturación ideal, $V_{CE} = 0\\text{ V}$.",
          "Pista 2: La resistencia total del lazo de colector es $R_C + R_E = 1.8\\text{ k}\\Omega + 1.2\\text{ k}\\Omega = 3.0\\text{ k}\\Omega$.",
          "Pista 3: $I_{C,sat} = \\frac{18\\text{ V}}{3.0\\text{ k}\\Omega} = 6.0\\text{ mA}$."
        ],
        "explicacion": "$I_{C,sat} = \\frac{V_{CC}}{R_C + R_E} = \\frac{18\\text{ V}}{1.8\\text{ k}\\Omega + 1.2\\text{ k}\\Omega} = \\frac{18\\text{ V}}{3.0\\text{ k}\\Omega} = 6.0\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 6,
        "valorEsperado": 6,
        "tolerancia": 0.05,
        "simbolo": "I_{C,sat}",
        "explicacionPaso": "$I_{C,sat} = \\frac{18\\text{ V}}{3.0\\text{ k}\\Omega} = 6.0\\text{ mA}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Tensión de reposo VCEQ para ICQ = 3 mA",
        "pregunta": "Calcule la tensión $V_{CEQ}$ en el punto medio de la recta si $I_{CQ} = 3.0\\text{ mA}$ (en Volts).",
        "pistas": [
          "Pista 1: Aplique la ecuación de la recta de carga: $V_{CEQ} = V_{CC} - I_{CQ} (R_C + R_E)$.",
          "Pista 2: $R_C + R_E = 3.0\\text{ k}\\Omega$. La caída total en las resistencias es $3.0\\text{ mA} \\cdot 3.0\\text{ k}\\Omega = 9.0\\text{ V}$.",
          "Pista 3: $V_{CEQ} = 18\\text{ V} - 9.0\\text{ V} = 9.0\\text{ V}$."
        ],
        "explicacion": "$V_{CEQ} = V_{CC} - I_{CQ}(R_C + R_E) = 18.0 - (3.0 \\cdot 3.0) = 18.0 - 9.0 = 9.0\\text{ V}$. Coincide con el punto de máxima excursión simétrica ($V_{CC}/2$).",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 9,
        "valorEsperado": 9,
        "tolerancia": 0.05,
        "simbolo": "V_{CEQ}",
        "explicacionPaso": "$V_{CEQ} = 18 - 3(3.0) = 9.0\\text{ V}$."
      }
    ]
