    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Corriente de base IB",
        "pregunta": "Calcule la corriente de base $I_B$ (en µA).",
        "pistas": [
          "Pista 1: La corriente que circula por $R_C$ es $(I_C + I_B) = (\\beta + 1) I_B$.",
          "Pista 2: Ecuación: $I_B = \\frac{V_{CC} - V_{BE}}{R_B + (\\beta + 1)(R_C + R_E)}$.",
          "Pista 3: Denominador: $270\\text{ k}\\Omega + 121(3.3\\text{ k}\\Omega + 0.68\\text{ k}\\Omega) = 270 + 121(3.98) = 270 + 481.58 = 751.58\\text{ k}\\Omega$. $I_B = 11.3 / 751.58\\text{ k}\\Omega = 15.03\\,\\mu\\text{A}$."
        ],
        "explicacion": "$I_B = \\frac{V_{CC} - V_{BE}}{R_B + (\\beta + 1)(R_C + R_E)} = \\frac{12 - 0.7}{270\\text{ k}\\Omega + 121 \\cdot 3.98\\text{ k}\\Omega} = \\frac{11.3\\text{ V}}{751.58\\text{ k}\\Omega} \\approx 15.04\\,\\mu\\text{A}$.",
        "tipoRespuesta": "numerica",
        "unidad": "µA",
        "solucion": 15.04,
        "tolerancia": 0.05,
        "simbolo": "I_B",
        "valorEsperado": 15.04,
        "explicacionPaso": "$I_B = \\frac{V_{CC} - V_{BE}}{R_B + (\\beta + 1)(R_C + R_E)} = \\frac{12 - 0.7}{270\\text{ k}\\Omega + 121 \\cdot 3.98\\text{ k}\\Omega} = \\frac{11.3\\text{ V}}{751.58\\text{ k}\\Omega} \\approx 15.04\\,\\mu\\text{A}$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente de colector ICQ",
        "pregunta": "Determine la corriente de reposo $I_{CQ}$ (en mA).",
        "pistas": [
          "Pista 1: Multiplique $I_B$ por la ganancia de corriente $\\beta = 120$.",
          "Pista 2: $I_C = \\beta I_B = 120 \\cdot 15.04\\,\\mu\\text{A}$.",
          "Pista 3: $1.805\\text{ mA}$."
        ],
        "explicacion": "$I_{CQ} = \\beta I_B = 120 \\cdot 15.04\\,\\mu\\text{A} \\approx 1.80\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 1.8,
        "tolerancia": 0.05,
        "simbolo": "I_{CQ}",
        "valorEsperado": 1.8,
        "explicacionPaso": "$I_{CQ} = \\beta I_B = 120 \\cdot 15.04\\,\\mu\\text{A} \\approx 1.80\\text{ mA}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Tensión de reposo VCEQ",
        "pregunta": "Calcule la tensión $V_{CEQ}$ (en Volts).",
        "pistas": [
          "Pista 1: $V_{CEQ} = V_{CC} - (I_C + I_B) R_C - I_E R_E \\approx V_{CC} - I_{CQ}(R_C + R_E)$.",
          "Pista 2: $12\\text{ V} - 1.805\\text{ mA}(3.3\\text{ k}\\Omega + 0.68\\text{ k}\\Omega) = 12 - 1.805(3.98) = 12 - 7.18 = 4.82\\text{ V}$.",
          "Pista 3: Otra forma: $V_{CEQ} = V_{BE} + I_B R_B = 0.7 + (15.04\\times 10^{-6})(270000) = 0.7 + 4.06 = 4.76\\text{ V}$."
        ],
        "explicacion": "A través de la rama colector-base: $V_{CEQ} = V_{BE} + I_B R_B = 0.7\\text{ V} + (15.04\\,\\mu\\text{A} \\cdot 270\\text{ k}\\Omega) = 0.7 + 4.06 = 4.76\\text{ V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 4.76,
        "tolerancia": 0.05,
        "simbolo": "V_{CEQ}",
        "valorEsperado": 4.76,
        "explicacionPaso": "A través de la rama colector-base: $V_{CEQ} = V_{BE} + I_B R_B = 0.7\\text{ V} + (15.04\\,\\mu\\text{A} \\cdot 270\\text{ k}\\Omega) = 0.7 + 4.06 = 4.76\\text{ V}$."
      }
    ]
