    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Carga efectiva de alterna en emisor",
        "pregunta": "Calcule la resistencia total de carga de alterna $r_L = R_E \\parallel R_L$ (en Ohms).",
        "pistas": [
          "Pista 1: En señal, el capacitor de acoplo es un cortocircuito, poniendo $R_L$ en paralelo con $R_E$.",
          "Pista 2: $r_L = (1500 \\cdot 1000) / (1500 + 1000)$.",
          "Pista 3: $1.5\\times 10^6 / 2500 = 600\\,\\Omega$."
        ],
        "explicacion": "$r_L = R_E \\parallel R_L = \\frac{1500 \\cdot 1000}{2500} = 600.0\\,\\Omega$.",
        "tipoRespuesta": "numerica",
        "unidad": "Ω",
        "solucion": 600,
        "tolerancia": 0.05,
        "simbolo": "r_L",
        "valorEsperado": 600,
        "explicacionPaso": "$r_L = R_E \\parallel R_L = 600.0\\,\\Omega$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Ganancia de tensión Av",
        "pregunta": "Calcule la ganancia de tensión $A_v = v_o / v_i$ (adimensional).",
        "pistas": [
          "Pista 1: En términos de parámetros híbridos: $A_v = \\frac{(1 + h_{fe}) r_L}{h_{ie} + (1 + h_{fe}) r_L}$.",
          "Pista 2: $(1 + h_{fe}) r_L = 121 \\cdot 600 = 72600\\,\\Omega$.",
          "Pista 3: $A_v = \\frac{72600}{1800 + 72600} = \\frac{72600}{74400} \\approx 0.976\\text{ V/V}$."
        ],
        "explicacion": "$A_v = \\frac{(1 + h_{fe}) r_L}{h_{ie} + (1 + h_{fe}) r_L} = \\frac{121 \\cdot 600}{1800 + 121 \\cdot 600} = \\frac{72600}{74400} \\approx 0.976\\text{ V/V}$.",
        "tipoRespuesta": "numerica",
        "unidad": "",
        "solucion": 0.976,
        "tolerancia": 0.05,
        "simbolo": "A_v",
        "valorEsperado": 0.976,
        "explicacionPaso": "$A_v = \\frac{(1 + h_{fe}) r_L}{h_{ie} + (1 + h_{fe}) r_L} \\approx 0.976\\text{ V/V}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Resistencia de entrada en base",
        "pregunta": "Determine la resistencia de entrada reflejada a la base $R_{ib}$ (en kΩ).",
        "pistas": [
          "Pista 1: La resistencia de entrada en base es $R_{ib} = h_{ie} + (1 + h_{fe}) r_L$.",
          "Pista 2: $h_{ie} = 1.8\\text{ k}\\Omega$ y $(1 + h_{fe}) r_L = 121 \\cdot 0.6\\text{ k}\\Omega = 72.6\\text{ k}\\Omega$.",
          "Pista 3: $R_{ib} = 1.8 + 72.6 = 74.4\\text{ k}\\Omega$."
        ],
        "explicacion": "$R_{ib} = h_{ie} + (1 + h_{fe}) r_L = 1.8\\text{ k}\\Omega + 121 \\cdot 0.6\\text{ k}\\Omega = 1.8 + 72.6 = 74.4\\text{ k}\\Omega$.",
        "tipoRespuesta": "numerica",
        "unidad": "kΩ",
        "solucion": 74.4,
        "tolerancia": 0.05,
        "simbolo": "R_{ib}",
        "valorEsperado": 74.4,
        "explicacionPaso": "$R_{ib} = h_{ie} + (1 + h_{fe}) r_L = 74.4\\text{ k}\\Omega$."
      }
    ]
